-- process_steps
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('01', 0, 'Discovery', 'Understanding the problem, feasibility analysis, and defining product requirements.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('02', 1, 'Architecture', 'Defining product architecture — hardware schematics, software stack, low-power constraints, and connectivity protocols — considering stability, cost, and user adaptability.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('03', 2, 'Prototype', 'Quick PoC with off-the-shelf development kits, or spinning initial PCB runs and developing first-stage firmware for lab testing.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('04', 3, 'Testing', 'Rigorous testing of board interfaces, range coverage, power profiles, and code reliability.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('05', 4, 'Pilot', 'Deploying a small batch of hardware units in real-world field environments to collect telemetry.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('06', 5, 'Production', 'Sourcing components, designing test jigs, and finalizing QA systems for volume assembly.');
INSERT INTO `process_steps` (`step`, `sort_order`, `name`, `description`) VALUES ('07', 6, 'Support', 'Rolling out secure FOTA updates and maintaining field hardware throughout its life cycle, including product after-life support for repair and bug fixes.');

